"use strict";window.addEventListener("DOMContentLoaded",d=>{const s=document.body.querySelector("#sidebarToggle");if(s){const e=localStorage.getItem("sb|sidebar-toggle");e==="true"?document.body.classList.add("sb-sidenav-toggled"):e==="false"&&document.body.classList.remove("sb-sidenav-toggled"),s.addEventListener("click",o=>{o.preventDefault(),document.body.classList.toggle("sb-sidenav-toggled"),localStorage.setItem("sb|sidebar-toggle",document.body.classList.contains("sb-sidenav-toggled"))})}const t=document.querySelector(".scroll-to-top");if(t){const e=()=>t.classList.toggle("is-visible",window.scrollY>400);window.addEventListener("scroll",e,{passive:!0}),e(),t.addEventListener("click",o=>{o.preventDefault(),window.scrollTo({top:0,behavior:"smooth"})})}});
